import json, sys
data = json.load(sys.stdin)
# Group by headword_norm
groups = {}
for r in data:
    k = r['headword_norm']
    if k not in groups:
        groups[k] = []
    groups[k].append(r)
for norm in sorted(groups.keys()):
    print(f'=== {norm} ({len(groups[norm])} entries) ===')
    for r in groups[norm][:5]:
        print(f'  id={r[\"entry_id\"]} hw={r[\"headword\"]} root={r[\"root\"]} pos={r[\"pos\"]} src={r[\"source_type\"]}')
        defn = (r.get('definitions_text') or '')[:200]
        if defn: print(f'    def: {defn}')
        if r.get('translation_en'): print(f'    en: {r[\"translation_en\"]}')
    if len(groups[norm]) > 5:
        print(f'  ... and {len(groups[norm])-5} more')
"
